//! 🧪️ Authored metadata preserves original allocations across bounded hashing and cancellation.
use super::*;
#[test]
fn original_native_checkout_command_returns_one_result_then_physically_closes(){
 type Metadata=store::ArtifactNativeVcsCommand<State,Mutation>;
 let fixture:serde_json::Value=serde_json::from_str(include_str!("checkout.json")).unwrap();
 for cut in fixture["cancelCuts"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize)).chain([Some(usize::MAX),None]){
 let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut store=native_document_store(&mut caller,&mut decoder);let g=RetainedCloneGrant{maximum_copy_bytes:32768,maximum_capacity_bytes:16<<20,..TURN};let result=semio_framework_os_store_engine_replay::prepare_report(&mut store,&mut caller,&mut decoder);crate::original_stream_abort::close_report_fixture(result,&mut caller,&mut decoder);
 let id=prepare_checkout_checkpoint(&mut store,&mut caller,&mut decoder);{let parts=store.parts();*parts.live.current=Arc::new(State{zoom:fixture["visibleBefore"].as_f64().unwrap()});}let transitions=store.parts_ref().log.envelope.transitions.len();let outbox=store.parts_ref().wire.original_outbox.len();let mut request=None;turn(&mut caller,&mut decoder,g,|cx|{let d=OriginalConstructionDemand{items:1,copy_bytes:2*size_of::<store::ArtifactNativeVcsRequest>()+id.len(),capacity_bytes:id.len(),release_bytes:0,depth:1};admit_original_construction(cx,&mut request,d,|_|Ok((store::ArtifactNativeVcsRequest::CheckoutCheckpoint{checkpoint_id:id.clone()},RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()})))?;Ok(())});let mut source=None;let birth=Metadata::capture_demands();for axis in [0,1,2,4]{let mut denied=g;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=birth.copy_bytes-1,2=>denied.maximum_capacity_bytes=birth.capacity_bytes-1,_=>denied.maximum_depth=0};turn(&mut caller,&mut decoder,denied,|cx|{assert!(!store.admit_native_vcs_command(&mut request,cx,&mut source)?);Ok(())});}turn(&mut caller,&mut decoder,g,|cx|{assert!(store.admit_native_vcs_command(&mut request,cx,&mut source)?);Ok(())});let mut foreign=OriginalJobDecodeOwner::empty();turn(&mut caller,&mut foreign,g,|cx|{assert!(store.advance_native_vcs_command(source.as_mut().unwrap(),cx).is_err());Ok(())});
 for index in 0..262144{if cut==Some(index)||source.as_ref().unwrap().borrow_result().is_some(){break}turn(&mut caller,&mut decoder,g,|cx|store.advance_native_vcs_command(source.as_mut().unwrap(),cx));assert!(index<262143);}if cut.is_none(){assert!(source.as_ref().unwrap().borrow_result().is_some());let mut result=None;turn(&mut caller,&mut decoder,g,|cx|{assert!(store.take_native_vcs_result(source.as_mut().unwrap(),cx,&mut result)?);Ok(())});assert_eq!(result.unwrap().kind,store::ArtifactNativeVcsKind::CheckoutCheckpoint);turn(&mut caller,&mut decoder,g,|cx|{assert!(store.ack_native_vcs_command(source.as_mut().unwrap(),cx)?);Ok(())});assert_eq!(store.snapshot().unwrap().zoom,fixture["visibleAfter"].as_f64().unwrap());assert_eq!(store.parts_ref().log.envelope.transitions.len(),transitions);assert_eq!(store.parts_ref().wire.original_outbox.len(),outbox);assert_eq!(store.parts_ref().log.current_checkpoint_id.as_deref(),Some(id.as_str()));assert_eq!(store.parts_ref().log.envelope.viewer_checkpoint_id.as_deref(),Some(id.as_str()));assert!(store.parts_ref().log.redo_edit_ids.is_empty());}else{caller.cancel().cancel_now();}
 for index in 0..262144{if source.as_ref().unwrap().terminal_is_empty(){break}let d=store.native_vcs_command_close_demands(source.as_ref().unwrap(),4096).unwrap();let exact=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};for axis in 0..5{let mut denied=exact;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes-=1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes-=1,3 if d.release_bytes>0=>denied.maximum_release_bytes-=1,4 if d.depth>0=>denied.maximum_depth-=1,_=>continue};turn(&mut caller,&mut decoder,denied,|cx|cx.with_original_retirement(|cx|{assert!(!store.close_native_vcs_command(source.as_mut().unwrap(),cx)?);Ok(())}));assert_eq!(store.native_vcs_command_close_demands(source.as_ref().unwrap(),4096).unwrap(),d);}turn(&mut caller,&mut decoder,exact,|cx|cx.with_original_retirement(|cx|store.close_native_vcs_command(source.as_mut().unwrap(),cx)));assert!(index<262143);}
 drop(source.take());let mut owned_id=Some(id);let mut id_close=semio_framework_value::retained_clone::RetainedCloneClose::default();while owned_id.is_some()||!id_close.is_empty(){turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=if id_close.is_empty(){id_close.next_owner_demands::<String>(true,&None,4096)?}else{id_close.demands(4096)?};close_original_retained_step(cx,d,|grant|if id_close.is_empty(){Ok(id_close.begin_granted(&mut owned_id,grant)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}else{id_close.step_granted(grant)})?;Ok(())}));}for index in 0..1048576{if store.close_owned_store_terminal_is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=store.close_owned_demands(4096)?;close_original_retained_step(cx,d,|grant|store.close_owned_store_step(grant))?;Ok(())}));assert!(index<1048575);}release_native_store_box(store,&mut caller,&mut decoder);while !decoder.terminal_is_empty(){caller.turn(g,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}caller.retire(g);
 }
}

fn prepare_checkout_checkpoint(store:&mut store::ArtifactStore<State,Mutation>,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner)->String{
 type Publisher=semio_framework_os_store_engine_replay::checkpoint::OriginalCheckpointPublication<Mutation>;let g=RetainedCloneGrant{maximum_copy_bytes:32768,maximum_capacity_bytes:16<<20,..TURN};let mut message=None;let mut authors=Vec::new();let mut publisher=None;turn(caller,decoder,g,|cx|{assert!(Publisher::admit(store,&mut message,&mut authors,cx,&mut publisher)?);Ok(())});for index in 0..262144{if turn(caller,decoder,g,|cx|publisher.as_mut().unwrap().advance(store,cx)){break}assert!(index<262143);}turn(caller,decoder,g,|cx|{assert!(publisher.as_mut().unwrap().publish(store,cx)?);Ok(())});for index in 0..262144{if publisher.as_ref().unwrap().terminal_is_empty(){break}turn(caller,decoder,g,|cx|cx.with_original_retirement(|cx|publisher.as_mut().unwrap().close_step(store,4096,cx)));assert!(index<262143);}turn(caller,decoder,g,|cx|cx.with_original_retirement(|cx|{let d=Publisher::boxed_release_demands();close_original_retained_step(cx,d,|_|{publisher=None;Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));let mut output=None;turn(caller,decoder,g,|cx|{let id=store.current_checkpoint_id().unwrap();let d=OriginalConstructionDemand{items:1,copy_bytes:id.len()+size_of::<String>(),capacity_bytes:id.len(),release_bytes:0,depth:1};admit_original_construction(cx,&mut output,d,|_|Ok((id.to_owned(),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()})))?;Ok(())});output.unwrap()
}
